GRANT EXECUTE ON FUNCTION org_store_score(uuid,jsonb,jsonb,jsonb,jsonb,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_assessment_attempt() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE priv boolean;BEGIN PERFORM pg_advisory_xact_lock(811112026);priv:=coalesce(auth.role(),'')='service_role' OR (auth.uid() IS NULL AND coalesce(current_setting('role',true),'none') NOT IN ('anon','authenticated'));IF (SELECT status FROM assessment_batteries WHERE id=NEW.battery_id)<>'approved' THEN RAISE EXCEPTION 'Candidate release requires HR approval';END IF;IF TG_OP='UPDATE' THEN IF NEW.id<>OLD.id OR NEW.battery_id<>OLD.battery_id THEN RAISE EXCEPTION 'Attempt version immutable';END IF;IF OLD.status IN ('submitted','scored') AND NEW.answers<>OLD.answers AND NEW.purged_at IS NULL THEN RAISE EXCEPTION 'Submitted answers immutable';END IF;IF NOT priv AND current_setting('app.score_action',true) IS DISTINCT FROM auth.uid()::text THEN RAISE EXCEPTION 'Scoring uses protected action';END IF;ELSIF NOT priv AND (NEW.token_hash IS NOT NULL OR NEW.status<>'invited') THEN RAISE EXCEPTION 'Invitation generation server controlled';END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION public.org_store_score(aid uuid,expected jsonb,rs jsonb,recs jsonb,sc jsonb,st text,item text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a assessment_attempts;oldothers jsonb;newothers jsonb;BEGIN PERFORM pg_advisory_xact_lock(811112026);SELECT * INTO a FROM assessment_attempts WHERE id=aid FOR UPDATE;IF NOT org_can('score',a.battery_id) THEN RAISE EXCEPTION 'Assigned Rater required';END IF;IF a.status NOT IN ('submitted','scored') OR a.purged_at IS NOT NULL OR a.raters IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Scoring changed; refresh and retry';END IF;IF NOT org_has_role(auth.uid(),'admin') THEN IF NOT EXISTS(SELECT 1 FROM assessment_rater_assignments r JOIN org_people p ON p.id=r.person_id WHERE r.attempt_id=aid AND r.item_id=item AND p.user_id=auth.uid()) THEN RAISE EXCEPTION 'Work sample assignment required';END IF;IF recs<>a.reconciliations THEN RAISE EXCEPTION 'Only Admin can reconcile';END IF;SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO oldothers FROM jsonb_array_elements(a.raters) WHERE value->>'user_id'<>auth.uid()::text OR value->>'item_id'<>item;SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO newothers FROM jsonb_array_elements(rs) WHERE value->>'user_id'<>auth.uid()::text OR value->>'item_id'<>item;IF oldothers<>newothers THEN RAISE EXCEPTION 'Other rater scores immutable';END IF;END IF;PERFORM set_config('app.score_action',auth.uid()::text,true);UPDATE assessment_attempts SET raters=rs,reconciliations=recs,scores=sc,status=st WHERE id=aid;RETURN true;END $$;
CREATE FUNCTION public.org_rater_assignment_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid;BEGIN SELECT battery_id INTO bid FROM assessment_attempts WHERE id=NEW.attempt_id;IF NOT EXISTS(SELECT 1 FROM org_people p JOIN org_person_roles r ON r.person_id=p.id JOIN org_assignments a ON a.person_id=p.id WHERE p.id=NEW.person_id AND p.status='active' AND r.role='rater' AND a.role_id=bid AND a.permission='rater') OR NOT EXISTS(SELECT 1 FROM assessment_batteries b CROSS JOIN LATERAL jsonb_array_elements(b.payload->'items') i WHERE b.id=bid AND i->>'id'=NEW.item_id AND i->>'method'='work_sample') THEN RAISE EXCEPTION 'Assign an active job-role Rater to a work sample';END IF;RETURN NEW;END $$;
CREATE TRIGGER rater_assignment_guard BEFORE INSERT OR UPDATE ON assessment_rater_assignments FOR EACH ROW EXECUTE FUNCTION org_rater_assignment_guard();
CREATE FUNCTION public.org_candidate_privacy_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE notice text;BEGIN IF TG_OP='INSERT' THEN SELECT privacy_notice INTO notice FROM org_settings WHERE id;NEW.privacy_notice:=coalesce(notice,'Your responses are assessed by authorized hiring staff. Optional demographics are separate from scoring. Contact the hiring team with privacy questions.');ELSIF NEW.status='in_progress' AND OLD.status='invited' AND NEW.privacy_accepted_at IS NULL THEN RAISE EXCEPTION 'Acknowledge privacy notice before starting';END IF;RETURN NEW;END $$;
CREATE TRIGGER candidate_privacy_guard BEFORE INSERT OR UPDATE ON assessment_attempts FOR EACH ROW EXECUTE FUNCTION org_candidate_privacy_guard();
CREATE POLICY legacy_active_people_gate ON user_roles AS RESTRICTIVE FOR ALL TO authenticated USING(org_active(auth.uid())) WITH CHECK(org_active(auth.uid()));
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['job_roles','role_analysis_versions','evidence_items','evidence_conflicts','conflict_evidence','competencies','competency_evidence','hiring_packages','package_materials','material_citations','contributions','approvals','interview_sessions','interview_sources','interview_answers','interview_outputs'] LOOP EXECUTE format('CREATE POLICY active_workspace_gate ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING(public.org_active(auth.uid()) AND (public.org_can(''analysis'') OR public.org_can(''approve''))) WITH CHECK(public.org_active(auth.uid()) AND (public.org_can(''analysis'') OR public.org_can(''approve'')))',t);END LOOP;END $$;